package main

import "fmt"

func removeDuplicates(nums []int) []int {
	result := []int{}
	for _, x := range nums {
		seen := false
		for _, y := range result {
			if y == x {
				seen = true
				break
			}
		}
		if !seen {
			result = append(result, x)
		}
	}
	return result
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&nums[i])
	}
	result := removeDuplicates(nums)
	for i, x := range result {
		if i > 0 {
			fmt.Print(" ")
		}
		fmt.Print(x)
	}
	fmt.Println()
}

